"""Run one named MCP default-scope check against exact frozen private inputs."""
import argparse
import json
import subprocess
from pathlib import Path

root=Path(__file__).resolve().parent.parent
tmp=root/'.tmp'
py=str(root/'agomtradepro/Scripts/python.exe')
parser=argparse.ArgumentParser()
parser.add_argument('tag')
parser.add_argument('--manifest',required=True)
args=parser.parse_args()
tag=args.tag
source=tmp/args.manifest
manifest=json.loads(source.read_text())
prod=[name for name in manifest['source_paths'] if name.startswith('sdk/agomtradepro') and '/tests/' not in name]
python_paths=[name for name in manifest['source_paths'] if name.endswith('.py')]
cwd=root
if tag.startswith('red-auth'):
    cwd=root/'sdk'
    cmd=['-m','pytest','-q','tests/test_sdk/test_upstream_authentication_status.py']
